class Inventario:
    def __init__(self):
        self.s = {}
    def add(self, p, q):
        self.s[p] = self.s.get(p, 0) + q
    def remove(self, p, q):
        if self.s.get(p, 0) < q:
            return False
        self.s[p] -= q
        return True
    def stock(self, p):
        return self.s.get(p, 0)
    def lista(self):
        it = [f"{p}:{q}" for p, q in sorted(self.s.items()) if q > 0]
