class Calculadora:
    def avaliar(self, s):
        self.t = [c for c in s if c != " "]
        self.i = 0
        return self.expr()
    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None
    def expr(self):
        v = self.term()
        while self.peek() in ("+", "-"):
            op = self.t[self.i]
            self.i += 1
            w = self.term()
            v = v + w if op == "+" else v - w
        return v
    def term(self):
        v = self.factor()
        while self.peek() in ("*", "/"):
            op = self.t[self.i]
            self.i += 1
            w = self.factor()
            if op == "*":
                v = v * w
            else:
                q = abs(v) // abs(w)
                v = q if (v >= 0) == (w > 0) else -q
        return v
    def factor(self):
        if self.peek() == "(":
            self.i += 1
            v = self.expr()
            self.i += 1
            return v
        n = 0
        while self.peek() is not None and self.peek().isdigit():
            n = n * 10 + int(self.t[self.i])
            self.i += 1
        return n
