class Hotel:
    def __init__(self, n):
        self.n = n
        self.res = {}
        self.next_id = 1
    def livre(self, q, a, b):
        return all(not (r[0] == q and a < r[2] and r[1] < b) for r in self.res.values())
    def reservar(self, q, a, b):
        if not self.livre(q, a, b):
            return "OCUPADO"
        i = self.next_id
        self.res[i] = (q, a, b)
        self.next_id += 1
        return str(i)
    def cancelar(self, i):
        return "OK" if self.res.pop(i, None) else "ERRO"
    def livres(self, d):
        busy = {q for q, a, b in self.res.values() if a <= d < b}
        return self.n - len(busy)
